/* Synthetic portal views. All amounts and records are demonstration data only. */
window.LakePortals = (() => {
  const {art,logo} = LakePublic;
  const cash = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
  const action = (name,label,style='text-link',extra='') => `<button class="${style}" data-action="${name}" ${extra}>${label} <span aria-hidden="true">→</span></button>`;
  const navs = {
    park:[['','Today','◷'],['renters','Renters','♧'],['money','Money','$'],['onsite','On site','⚑'],['lots','Lots & rates','▦'],['setup','Park setup','⚙']],
    renter:[['','My home','⌂'],['bills','My bill','▤'],['updates','Office updates','☷'],['care','Home services','✧']],
    homeowner:[['','Overview','⌂'],['requests','My requests','☷'],['approvals','Approvals','✓'],['messages','Messages','☏'],['property','My property','▦'],['billing','Billing','▤']]
  };
  const labels = {park:'Park office',renter:'Renter',homeowner:'Homeowner'};
  const heading = (eyebrow,title,description,button='') => `<div class="workspace-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${button}</div>`;
  const task = (symbol,title,description,button,gold=true) => `<div class="task-row"><span class="task-marker ${gold?'':'teal'}" aria-hidden="true">${symbol}</span><div class="task-copy"><strong>${title}</strong><p>${description}</p></div>${button}</div>`;
  const events = () => `<div class="event-line"><div class="date-tile"><span>OCT</span><b>28</b></div><div><strong>Pier removal</strong><p>Lake home · Crew assigned</p></div><span class="pill teal">Scheduled</span></div><div class="event-line"><div class="date-tile"><span>NOV</span><b>02</b></div><div><strong>Seasonal closing</strong><p>Suggested date · No booking yet</p></div><span class="pill gold">Your choice</span></div>`;
  const miniServices = () => `<div class="mini-service-grid">${[['house','Seasonal care','Opening & closing'],['pier','Piers & lifts','Seasonal water work'],['mow','Lawn care','Available yard services'],['clean','Housekeeping','Care between stays']].map(([a,t,p])=>`<article class="mini-service">${art(a)}<b>${t}</b><p>${p}</p>${action('request-service','Request care','text-link',`data-service="${t}"`)}</article>`).join('')}</div>`;
  const rentRows = s => [
    {lot:'01',name:'Alex Morgan',charge:515,paid:100+s.confirmedExtra,pending:s.report?.status==='pending'?s.report.amount:0},
    {lot:'02',name:'Jamie Lee',charge:540,paid:540,pending:0},
    {lot:'03',name:'Sam Reed',charge:500,paid:275,pending:0},
    {lot:'04',name:'Taylor Quinn',charge:625,paid:625,pending:0}
  ];
  const totals = s => {const rows=rentRows(s);return {charges:2180,paid:rows.reduce((n,r)=>n+r.paid,0),due:rows.reduce((n,r)=>n+r.charge-r.paid,0),pending:rows.reduce((n,r)=>n+r.pending,0)}};
  const rollTable = (s,filter='all',search='') => {
    const rows=rentRows(s).filter(r=>(filter==='all'||(filter==='review'?r.pending>0:r.charge>r.paid))&&`${r.lot} ${r.name}`.toLowerCase().includes(search.toLowerCase()));
    return `<div class="table-wrap"><table><caption class="sr-only">October 2026 sample rent roll</caption><thead><tr><th scope="col">Resident / lot</th><th scope="col">Charges</th><th scope="col">Confirmed</th><th scope="col">Balance</th><th scope="col">Status</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><button class="row-link" data-action="resident" data-lot="${r.lot}">${r.name}</button><small>Lot ${r.lot}</small></td><td>${cash(r.charge)}</td><td>${cash(r.paid)}</td><td class="cell-amount">${cash(r.charge-r.paid)}</td><td>${r.pending?`<span class="pill gold">${cash(r.pending)} report to review</span>`:r.charge>r.paid?'<span class="pill">Balance due</span>':'<span class="pill green">Paid</span>'}</td></tr>`).join(''):'<tr><td colspan="5">No residents match this view. Try another name or filter.</td></tr>'}</tbody></table></div><p class="table-hint small-copy muted">Scroll the rent roll sideways on a small screen.</p>`;
  };
  const moneyPanel = s => {const t=totals(s);return `<section class="panel dark"><span class="eyebrow light">OCTOBER 2026 · RENT ROLL</span><div class="metric">${cash(t.due)}</div><p class="small-copy muted">Balance outstanding</p><div class="meter" aria-hidden="true"><i style="width:${t.paid/t.charges*100}%"></i></div><div class="money-breakdown"><div><span>Charges</span><b>${cash(t.charges)}</b></div><div><span>Confirmed receipts</span><b>${cash(t.paid)}</b></div></div><p class="small-copy" style="color:#c4dce3;margin:18px 0 0">${t.pending?`${cash(t.pending)} reported payment still needs review. It is not included in confirmed receipts.`:'No payment reports awaiting review in this example.'}</p></section>`};
  const parkToday = s => `${heading('LAKESIDE PARK · EXAMPLE','Your day, in view.','Start with the records that need your attention.','<a class="button" href="#/park/renters">Open rent roll <span aria-hidden="true">→</span></a>')}<div class="workspace-grid"><section class="panel"><div class="panel-title"><h2>Needs your attention</h2><span class="pill gold">${s.report?.status==='pending'?3:2} items</span></div>${s.report?.status==='pending'?task('$','A payment report to review',`Lot 01 · ${cash(s.report.amount)} reported · Not yet credited`,action('review-payment','Review')):task('✓','Payment report reviewed','Lot 01 · The confirmed record is reflected in the bill.',action('review-payment','View'),false)}${task('☷','Two resident issues are open','Lot 01 · Water connection / Lot 03 · Path light',action('issues','View'),false)}${task('⚑','Park mowing is on the calendar','Oct 28 · One assigned visit', '<a class="text-link" href="#/park/onsite">View →</a>',false)}</section>${moneyPanel(s)}</div><section class="dashboard-section"><div class="section-label"><h2>The rent roll, at a glance.</h2><a class="text-link" href="#/park/renters">All residents →</a></div>${rollTable(s)}</section><div class="workspace-grid dashboard-section"><section class="panel"><div class="panel-title"><h2>Park snapshot</h2><span class="pill">4 example lots</span></div><div class="stats-inline"><div><b>4 / 4</b><span>Occupied lots</span></div><div><b>2</b><span>Open issues</span></div><div><b>1</b><span>Scheduled park visit</span></div></div><p class="panel-note teal">Household service requests and prices stay separate from the park’s work and rent roll.</p></section><section class="panel"><span class="eyebrow">OCTOBER SHARED COST</span><h2>Water, clearly divided.</h2><p class="small-copy muted" style="margin-top:13px">$60 across four eligible lots = $15 per lot in this example.</p>${action('water-source','View source & allocation')}</section></div>`;
  const parkRenters = s => `${heading('OCTOBER RENT ROLL','Your residents. One clear roll.','October 2026 · Four occupied example lots')}<div class="toolbar"><label class="sr-only" for="resident-search">Search resident name or lot</label><input id="resident-search" class="search-input" type="search" placeholder="Search name or lot…" autocomplete="off"><div class="filter-pills" role="group" aria-label="Rent roll filter">${[['all','All residents'],['review','Needs review'],['balance','Balance due']].map(([f,l])=>`<button data-filter="${f}" class="${f==='all'?'active':''}" aria-pressed="${f==='all'}">${l}</button>`).join('')}</div></div><div id="rent-results">${rollTable(s)}</div><div class="panel-note">Pending payment reports are visible here, but only confirmed receipts reduce the balance. Confirming an offline receipt records a payment already made; it does not collect money.</div>`;
  const parkMoney = s => `${heading('PARK MONEY','The story behind the balance.','Rent, receipts and shared costs—kept in their own places.')}<div class="workspace-grid">${moneyPanel(s)}<section class="panel"><span class="eyebrow">PAYMENT READINESS</span><h2>Online payments unavailable</h2><p class="small-copy muted" style="margin-top:16px">This preview has no connected receiving account or active payment methods. In the platform, payment options depend on the park’s readiness and enabled capabilities.</p><button class="button quiet small" disabled>Online collection unavailable</button><p class="panel-note">Residents can use the park’s usual payment method and report an already-made payment for office review.</p></section></div><section class="panel dashboard-section"><div class="panel-title"><h2>October shared charges</h2>${action('water-source','View supporting record')}</div><div class="statement-row"><span>Water utility · Example source total</span><b>$60</b></div><div class="statement-row"><span>Eligible occupied lots</span><b>4</b></div><div class="statement-row total"><span>Allocation per lot</span><b>$15</b></div><p class="small-copy muted" style="margin-top:15px">The example shows equal allocation. Actual allocation follows the park’s configured rules and eligible residents.</p></section><div class="panel-note teal">LakeLife platform fees have their own records. Household optional-service charges are not part of this rent view.</div>`;
  const parkOnsite = () => `${heading('ON SITE','What’s happening around the park.','Park work stays separate from residents’ optional home services.')}<div class="workspace-grid"><section class="panel"><div class="panel-title"><h2>Scheduled park work</h2><span class="pill">October</span></div><div class="event-line"><div class="date-tile"><span>OCT</span><b>28</b></div><div><strong>Park mowing</strong><p>Common grounds · Example assigned crew</p></div><span class="pill teal">Scheduled</span></div><p class="panel-note teal">This is a synthetic appointment. A requested date alone would not appear as confirmed.</p></section><section class="panel"><span class="eyebrow">RESIDENT ISSUES</span><h2>Two records to follow.</h2><p class="small-copy muted" style="margin-top:16px">Water connection · Lot 01<br>Path light · Lot 03</p>${action('issues','Review recorded updates','button quiet small')}</section></div>`;
  const parkLots = () => `${heading('LOTS & RATES','The shape of your park.','Example records only. Rates shown here are not LakeLife defaults.')}<div class="table-wrap"><table><caption class="sr-only">Example park lots and charges</caption><thead><tr><th>Lot</th><th>Resident</th><th>October rent</th><th>Other charges</th><th>Occupancy</th></tr></thead><tbody>${[['01','Alex Morgan',500,15],['02','Jamie Lee',525,15],['03','Sam Reed',485,15],['04','Taylor Quinn',610,15]].map(([lot,n,r,c])=>`<tr><td><b>${lot}</b></td><td>${n}</td><td>${cash(r)}</td><td>${cash(c)} water</td><td><span class="pill teal">Occupied</span></td></tr>`).join('')}</tbody></table></div><div class="panel-note">Published bills, agreed rates and existing records must retain their current rules. This design preview does not edit rates or reprice residents.</div>`;
  const parkSetup = () => `${heading('PARK SETUP','A good setup starts with the details.','A view of the information your park’s configuration depends on.')}<div class="workspace-grid"><section class="panel"><h2>Lakeside Park</h2><p class="small-copy muted" style="margin-top:15px">Fictional park · Four occupied lots</p><div class="statement-row"><span>Rent roll</span><span class="pill teal">Sample loaded</span></div><div class="statement-row"><span>Online receiving account</span><span class="pill">Not connected</span></div><div class="statement-row"><span>Payment methods</span><span class="pill">Unavailable</span></div><div class="statement-row"><span>Office access</span><span class="pill">Sample membership</span></div></section><section class="panel"><span class="eyebrow">GUIDED, WITH YOUR PARK</span><h2>Review before rollout.</h2><p class="small-copy muted" style="margin-top:16px">Your rent roll, fees, resident links, access permissions and payment readiness need to be checked against the actual park setup.</p><a class="button quiet small" href="#/get-started">Explore a walkthrough →</a><p class="panel-note">Preview controls never grant park access or turn payments on.</p></section></div>`;
  const renterBill = s => {const due=415-s.confirmedExtra;return `<section class="panel balance-panel"><div class="panel-title"><h2>Your October bill</h2><span class="pill">Lot 01</span></div><div class="metric" data-renter-balance>${cash(due)}</div><p class="bill-meta">Balance due · October 2026</p><div class="statement-row"><span>Monthly lot rent</span><b>$500</b></div><div class="statement-row"><span>Shared water charge</span><b>$15</b></div><div class="statement-row credit"><span>Confirmed receipts</span><b>−${cash(100+s.confirmedExtra)}</b></div><div class="statement-row total"><span>Remaining balance</span><b>${cash(due)}</b></div>${s.report?.status==='pending'?`<p class="panel-note">${cash(s.report.amount)} reported payment is awaiting office review. It has not reduced this balance.</p>`:s.confirmedExtra?`<p class="panel-note teal">The office confirmed your ${cash(s.confirmedExtra)} additional payment record in this example.</p>`:''}<div class="actions" style="margin-top:22px">${action('payment-options','How to pay','button small')}${s.report?.status==='pending'||due>0?action(s.report?.status==='pending'?'review-payment':'report-payment',s.report?.status==='pending'?'View my payment report':'I’ve already paid','button light small'):''}</div></section>`};
  const renterUpdates = () => `<section class="panel"><div class="panel-title"><h2>From your park office</h2><span class="pill">1 open issue</span></div><div class="task-row"><span class="task-marker teal" aria-hidden="true">☷</span><div class="task-copy"><strong>Water at your lot connection</strong><p>Oct 16 · Office has recorded your report.</p></div></div><p class="small-copy muted">Status: In review. There is no confirmed repair date in this example.</p>${action('resident-issue','View the update','text-link')}<div class="quiet-divider"><div><h3>Need to reach the office?</h3><p>Follow your park’s usual contact method for questions about your stay.</p></div></div>${action('office-contact','Office & payment help')}</section>`;
  const renterHome = s => `<div class="renter-hero"><div><span class="eyebrow gold">LAKESIDE PARK · LOT 01 · EXAMPLE</span><h1>Welcome home, Alex.</h1><p>Your bill, your records, your place at the lake.</p></div>${art('renter')}</div><div class="workspace-grid">${renterBill(s)}${renterUpdates()}</div><div class="quiet-divider"><div><span class="eyebrow">FOR YOUR HOME, IF YOU NEED IT</span><h2>A little help around your place.</h2><p>Optional services are requested and charged separately from park rent.</p></div><span class="pill teal">Availability varies</span></div>${miniServices()}`;
  const renterBills = s => `${heading('MY BILL & RECEIPTS','Know where your balance stands.','Only confirmed receipts reduce the amount due.')}<div class="workspace-grid">${renterBill(s)}<section class="panel"><h2>Receipt history</h2><div class="statement-row"><span>Oct 05 · Office-confirmed receipt</span><b>$100</b></div>${s.confirmedExtra?`<div class="statement-row"><span>Additional confirmed example receipt</span><b>${cash(s.confirmedExtra)}</b></div>`:''}<p class="panel-note teal">These records describe payments already made. They do not initiate a transfer or collect funds.</p>${action('water-source','Understand the water charge')}</section></div>`;
  const renterCare = s => `${heading('OPTIONAL HOUSEHOLD SERVICES','Make a little room for lake time.','Available services for your household are separate from park rent.')}<div class="panel-note teal">Some requests need a crew quote. A request can remain unpriced, and a requested date is not a confirmed appointment.</div>${miniServices()}${s.requests.filter(r=>r.audience==='renter').length?`<section class="panel dashboard-section"><h2>Your example service requests</h2>${s.requests.filter(r=>r.audience==='renter').map(r=>`<div class="statement-row"><span>${LakeEscape(r.service)}<br><small>${LakeEscape(r.date)} · Date not confirmed</small></span><span class="pill">Price pending</span></div>`).join('')}</section>`:''}`;
  const homeownerHome = s => `${heading('MY LAKE HOME · BIG LONG LAKE · EXAMPLE','More lake time.<br>Less to keep track of.','See what’s scheduled, what needs a decision and what comes next.',action('request-service','Request a service','button'))}<div class="workspace-grid"><section class="panel"><div class="panel-title"><h2>A little attention, then back to life.</h2><span class="pill gold">Your next steps</span></div>${task('🍂',s.seasonal==='skipped'?'Seasonal suggestion skipped':s.seasonal==='requested'?'Seasonal request created':'Seasonal closing is suggested',s.seasonal==='skipped'?'No booking was made.':s.seasonal==='requested'?'Price pending · Date not confirmed':'Suggested Nov 02 · You choose to request or skip.',action('seasonal','Review'))}${task('🌊','A pier detail needs your review','Crew proposed 10 sections; your profile says 8.',action('correction','Review'),false)}${task('🌱','Lawn care is awaiting a quote','Requested Oct 30 · Date not confirmed','<a class="text-link" href="#/homeowner/requests">View →</a>',false)}</section><section class="panel"><div class="panel-title"><h2>The season ahead</h2><span class="pill">Example</span></div>${events()}<p class="panel-note teal">Water-work dates must follow your lake’s seasonal rules and the assigned crew’s schedule.</p></section></div><section class="dashboard-section"><div class="section-label"><h2>What can we help with?</h2><a class="text-link" href="#/services">Explore services →</a></div>${miniServices()}</section><div class="workspace-grid dashboard-section"><section class="panel"><div class="panel-title"><h2>Your lake-home details</h2><a class="text-link" href="#/homeowner/property">View profile →</a></div><div class="property-photo"><span class="photo-caption">Illustrative scene · Not a customer property</span></div><div class="profile-meta"><div><span>Lake</span><b>Big Long Lake</b></div><div><span>Pier profile</span><b>8 sections on record</b></div></div></section><section class="panel"><span class="eyebrow">THE RECORD STAYS WITH THE VISIT</span><h2>Know where things stand.</h2><div class="journey-list"><div class="journey-row done"><span class="journey-dot">✓</span><div><b>Request recorded</b><p>Your service details and preferred date.</p></div></div><div class="journey-row"><span class="journey-dot">2</span><div><b>Pricing & scheduling</b><p>Visible updates as each is resolved.</p></div></div><div class="journey-row"><span class="journey-dot">3</span><div><b>Visit & evidence</b><p>Required completion photos belong to the job record.</p></div></div></div><a class="text-link" href="#/homeowner/requests">View your requests →</a></section></div>`;
  const requests = s => `${heading('MY REQUESTS','Every request has a place.','Pricing and scheduling each keep their own status.',action('request-service','Request a service','button'))}<div class="panel">${[{service:'Pier removal',date:'Oct 28',price:'$360 · Example customer total',status:'Scheduled'},{service:'Lawn care',date:'Oct 30 requested',price:'Price pending',status:'Requested'},...s.requests.filter(r=>r.audience==='homeowner')].map((r,i)=>`<div class="request-row"><div>${art(i===0?'pier':i===1?'mow':'house')}<div><h2>${LakeEscape(r.service)}</h2><p class="small-copy muted">${LakeEscape(r.date)}${r.status!=='Scheduled'?' · Date not confirmed':''}</p></div></div><div><b class="small-copy">${LakeEscape(r.price)}</b><span class="pill ${r.status==='Scheduled'?'teal':''}">${r.status}</span></div></div>`).join('')}<p class="panel-note teal">A pending quote is never shown as $0. These example requests do not book work, accept a quote or charge a card.</p></div>`;
  const approvals = () => `${heading('APPROVALS','Your property. Your say.','Proposed corrections stay separate until you approve them.')}<section class="panel" style="max-width:800px"><div class="panel-title"><h2>Review the pier section count</h2><span class="pill gold">Needs review</span></div><p class="small-copy muted">The assigned crew has proposed a correction to your property details.</p><div class="profile-meta"><div><span>Currently on your profile</span><b>8 sections</b></div><div><span>Crew’s proposed count</span><b>10 sections</b></div></div><p class="panel-note">No profile or price has changed. The applicable pricing rules must be checked when the correction is approved.</p><div class="actions" style="margin-top:20px">${action('correction','Review correction','button small')}</div></section>`;
  const property = () => `${heading('MY PROPERTY','The details behind good care.','Your current record stays intact until an authorized change.')}<div class="workspace-grid"><section class="panel"><div class="property-photo" style="height:260px"><span class="photo-caption">Illustrative scene · Not a customer property</span></div><h2>My Big Long lake home</h2><div class="profile-meta"><div><span>Lake</span><b>Big Long Lake</b></div><div><span>Profile status</span><b>Example record</b></div><div><span>Pier</span><b>8 sections on record</b></div><div><span>Correction</span><b>10 sections proposed</b></div></div></section><section class="panel"><span class="eyebrow">CARE WITH CONTEXT</span><h2>A proposed change?</h2><p class="small-copy muted" style="margin-top:16px">Review the crew’s note before changing your record. A proposal by itself changes nothing and bills nothing.</p><a class="button quiet small" href="#/homeowner/approvals">Review the proposal →</a><p class="panel-note teal">Access instructions remain protected. This preview contains no gate codes, door codes or private addresses.</p></section></div>`;
  const billing = () => `${heading('MY BILLING','Charges with context.','Customer amounts belong here. Internal fees and crew payout details do not.')}<div class="workspace-grid"><section class="panel"><h2>Service amounts</h2><div class="statement-row"><span>Pier removal · Scheduled example</span><b>$360</b></div><div class="statement-row"><span>Lawn care · Quote requested</span><span class="pill">Price pending</span></div><p class="panel-note">These are illustrative service amounts, not a payment receipt or a claim that any charge was collected.</p></section><section class="panel"><span class="eyebrow">PAYMENT METHODS</span><h2>Payments are unavailable here.</h2><p class="small-copy muted" style="margin-top:16px">This local preview cannot store card details, tokenize a card or collect payment.</p><button class="button quiet small" disabled>Add payment method unavailable</button><p class="small-copy muted" style="margin-top:16px">The actual app must keep its existing payment-readiness checks and secure hosted fields.</p></section></div>`;
  const parkGroups = {
    renters:[['renters','Rent roll'],['onboard','Who lives here'],['documents','Documents']],
    money:[['money','Rent'],['costs','Costs & fees'],['statements','Statements']],
    onsite:[['onsite',"Who's on site"],['services','Park services']],
    lots:[['lots','Lots & rates'],['amenities','Things you rent out']],
    setup:[['setup','Park setup'],['import','Load the roll'],['people','Who can open this park']]
  };
  const detailScreens = {
    onboard: s => `${heading('RENTERS','Who lives here','The people linked to each example lot.')}<section class="panel">${rentRows(s).map(r=>`<div class="statement-row"><span><b>${r.name}</b><br>Lot ${r.lot}</span><span class="pill teal">Active stay</span></div>`).join('')}<p class="panel-note teal">Resident links and stay records determine access to a household’s own information. Moving out must not hide final bills or deposit records.</p></section>`,
    documents: () => `${heading('RENTERS','Documents','A place for the park’s resident documents.')}<section class="empty-state">${art('house')}<h2>No example documents attached.</h2><p>The production document workflow stays available. This preview contains no leases or private household files.</p></section>`,
    costs: () => `${heading('MONEY','Costs & fees','Keep supporting records beside the allocation.')}<section class="panel"><div class="statement-row"><span><b>October water charge</b><br>Four eligible lots · Equal-share example</span><b>$60 total</b></div><div style="margin-top:20px">${action('water-source','Review allocation','button quiet small')}</div><p class="panel-note">Park charges and LakeLife platform fees remain separate. This preview does not set a fee or create a billing rule.</p></section>`,
    statements: s => `${heading('MONEY','Statements','A readable October summary for the example park.')}<section class="panel"><div class="statement-row"><span>Charges</span><b>${cash(totals(s).charges)}</b></div><div class="statement-row"><span>Confirmed receipts</span><b>${cash(totals(s).paid)}</b></div><div class="statement-row total"><span>Outstanding balance</span><b>${cash(totals(s).due)}</b></div><p class="panel-note teal">This is an on-screen sample summary. Preserve the platform’s existing statements and export behavior during implementation.</p></section>`,
    services: () => `${heading('ON SITE','Park services','Work for the common grounds, separate from household service requests.')}<section class="panel"><div class="event-line"><div class="date-tile"><span>OCT</span><b>28</b></div><div><strong>Park mowing</strong><p>Common grounds · Example assigned crew</p></div><span class="pill teal">Scheduled</span></div><p class="panel-note teal">Actual service eligibility and park pricing rules remain authoritative. This preview does not create a park order.</p></section>`,
    amenities: () => `${heading('LOTS & RATES','Things you rent out','Keep the park’s rentable items in their own records.')}<section class="empty-state">${art('boat')}<h2>No example inventory added.</h2><p>Existing inventory, reservation and pricing rules remain in the actual app. This preview does not claim availability or assign a new price.</p></section>`,
    import: () => `${heading('PARK SETUP','Load the roll','Bring the existing records into view before adopting a new workflow.')}<section class="panel" style="max-width:800px"><h2>Your rent roll is already here.</h2><p class="small-copy muted" style="margin-top:18px">Four fictional residents are loaded for this design review. The production importer, its review steps and its existing safety checks stay intact.</p><a class="button quiet small" href="#/park/renters">View example rent roll →</a><p class="panel-note">No real file can be uploaded through this local preview.</p></section>`,
    people: () => `${heading('PARK SETUP','Who can open this park','Park access follows membership, not the screen someone selects.')}<section class="panel"><div class="statement-row"><span><b>Example park owner</b><br>Lakeside Park</span><span class="pill teal">Owner</span></div><p class="panel-note teal">The production invitation, acceptance and permission checks remain authoritative. No invitations or account changes can be made here.</p></section>`
  };
  const messages = () => `${heading('MESSAGES','A place for the conversation.','Talk with LakeLife dispatch about your property.')}<section class="panel" style="max-width:800px"><div class="empty-state" style="border:0;padding:25px 0">${art('lakelife-mark')}<h2>No example messages yet.</h2><p>This local view shows where your property conversation belongs. It cannot contact dispatch or send a notification.</p></div><form id="message-draft-form"><div class="field"><label for="message-draft">Your message</label><textarea id="message-draft" name="message" required maxlength="500" placeholder="Use example details for this preview."></textarea></div><button class="button small" type="submit">Preview message →</button></form></section>`;
  function render(role,page,s){
    const current=page||'';
    const nav=navs[role];
    const group=role==='park'?Object.keys(parkGroups).find(g=>parkGroups[g].some(([r])=>r===current)):null;
    const active=group||current;
    const subnav=group?`<nav class="tabs" aria-label="${nav.find(([r])=>r===group)?.[1]} pages">${parkGroups[group].map(([r,l])=>`<a href="#/park/${r}" ${r===current?'class="active" aria-current="page"':''}>${l}</a>`).join('')}</nav>`:'';
    const navLinks=nav.map(([r,l,i])=>`<a href="#/${role}${r?'/'+r:''}" ${r===active?'class="active" aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${i}</span>${l}${role==='homeowner'&&r==='approvals'?'<span class="nav-count">1</span>':''}</a>`).join('');
    const screens={park:{'':parkToday,renters:parkRenters,money:parkMoney,onsite:parkOnsite,lots:parkLots,setup:parkSetup,...detailScreens},renter:{'':renterHome,bills:renterBills,updates:()=>`${heading('OFFICE UPDATES','Your park’s record, in view.','Recorded updates about your stay.')}<div style="max-width:800px">${renterUpdates()}</div>`,care:renterCare},homeowner:{'':homeownerHome,requests,approvals,messages,property,billing}};
    const content=(screens[role][current]||screens[role][''])(s);
    return `<header class="workspace-header">${logo}<span class="workspace-type">${labels[role]}</span><div class="account"><span>${role==='park'?'Lakeside Park':'Alex Morgan'}</span><span class="avatar" aria-label="Example account">${role==='park'?'LP':'AM'}</span></div></header><div class="workspace"><aside class="sidebar"><div class="workspace-identity"><small>${role==='homeowner'?'MY PROPERTY':'MY PARK'}</small><b>${role==='homeowner'?'Big Long lake home':'Lakeside Park'}</b><span>${role==='renter'?'Lot 01 · ':''}Example account</span></div><nav class="side-nav" aria-label="${labels[role]} navigation">${navLinks}</nav><div class="sidebar-bottom">A little less to manage.<br>A little more lake life.<a href="#/home">Explore LakeLife →</a>${art('lakelife-wave-divider','footer-wave')}</div></aside><main id="main" class="workspace-main" tabindex="-1"><div class="workspace-topline"><span class="breadcrumbs">${labels[role]} / ${(group?parkGroups[group].find(([r])=>r===current)?.[1]:nav.find(([r])=>r===current)?.[1])||'Overview'}</span><span class="view-badge">SAMPLE RECORDS · OCT 2026</span></div>${role==='park'?'<div class="park-context"><span><b>Lakeside Park</b> <span class="pill">Example only</span></span>'+action('take-payment','Take a payment','button gold small')+'</div>':''}${subnav}${content}<div class="sample-footer"><span>Synthetic names, dates and amounts. No live actions or account access.</span><span>LakeLife · Design review</span></div></main></div><nav class="mobile-bottom" aria-label="${labels[role]} mobile navigation">${navLinks}</nav>`;
  }
  return {render,rollTable,rentRows,totals,cash};
})();
